div.script:
document.addEventListener('DOMContentLoaded', function () {
    var wrapper = document.querySelector('.switch-login-wrapper');
    if (!wrapper) return;

    // 1. Clean Eye Icon inside Password Field (no extra SHOW button)
    var eyeBtn = document.querySelector('.o_show_password');
    if (eyeBtn) {
        if (wrapper.getAttribute('data-pwd-toggle') === '0') {
            eyeBtn.style.display = 'none';
        } else {
            var eyeSvg = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>';
            eyeBtn.innerHTML = eyeSvg;
        }
    }

    // 2. Remember My Email Checkbox
    if (wrapper.getAttribute('data-remember-email') === '1') {
        var loginInput = document.querySelector('input#login, input[name="login"]');
        var form = document.querySelector('form.oe_login_form');
        if (loginInput && form && !form.querySelector('.switch-remember-row')) {
            var savedEmail = localStorage.getItem('odoo_saved_login_email');
            if (savedEmail && !loginInput.value) {
                loginInput.value = savedEmail;
            }

            var rememberDiv = document.createElement('div');
            rememberDiv.className = 'switch-remember-row form-check mb-3 mt-2';

            var checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.id = 'switch_remember_email';
            checkbox.className = 'form-check-input';
            checkbox.checked = Boolean(savedEmail);

            var label = document.createElement('label');
            label.htmlFor = 'switch_remember_email';
            label.className = 'form-check-label switch-remember-label';
            label.textContent = 'Remember my email';

            rememberDiv.appendChild(checkbox);
            rememberDiv.appendChild(label);

            var pwdFieldGroup = form.querySelector('.o_caps_lock_warning') || form.querySelector('.field-password') || (document.querySelector('input#password') && document.querySelector('input#password').closest('.mb-3'));
            if (pwdFieldGroup && pwdFieldGroup.parentNode) {
                pwdFieldGroup.parentNode.insertBefore(rememberDiv, pwdFieldGroup.nextSibling);
            } else {
                form.appendChild(rememberDiv);
            }

            form.addEventListener('submit', function () {
                if (checkbox.checked && loginInput.value) {
                    localStorage.setItem('odoo_saved_login_email', loginInput.value.trim());
                } else {
                    localStorage.removeItem('odoo_saved_login_email');
                }
            });
        }
    }
});

